?><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 mb-1"><?= $reservation?'Editar reserva':'Nova reserva' ?></h1></div><a class="btn btn-outline-secondary" href="index.php">Voltar</a></div><div class="row justify-content-center"><div class="col-lg-8"><div class="app-card"><form method="post" id="reservationForm"><input type="hidden" name="id" value="<?= $reservation['id']??'' ?>"><div class="row"><div class="col-md-4 mb-3"><label class="form-label">Grupo</label><select class="form-select" name="grupo_id" id="group" required><option value="">Selecione</option><?php foreach($groups as $group): ?><option value="<?= $group['id'] ?>" data-special="<?= $group['especial'] ?>" <?= ($reservation['grupo_id']??'')==$group['id']?'selected':'' ?>><?= e($group['nome']) ?></option><?php endforeach; ?></select></div><div class="col-md-4 mb-3"><label class="form-label">Área</label><select class="form-select" name="area_id" id="areaSelect" required><option value="">Selecione</option><?php foreach($areas as $area): ?><option value="<?= $area['id'] ?>" <?= ($reservation['area_id']??'')==$area['id']?'selected':'' ?>><?= e($area['nome']) ?> (<?= e($area['lugares']) ?> lugares)</option><?php endforeach; ?></select><div class="mt-2"><div class="form-check form-switch"><input class="form-check-input" type="checkbox" role="switch" id="multiAreaToggle"><label class="form-check-label" for="multiAreaToggle">Selecionar mais de uma área</label></div><div id="multiAreaBox" class="d-none border rounded p-2 mt-2"><?php foreach($areas as $area): ?><div class="form-check"><input class="form-check-input" type="checkbox" name="area_ids[]" id="area_<?= $area['id'] ?>" value="<?= $area['id'] ?>" <?= in_array((int)$area['id'],$selectedAreaIds,true)?'checked':'' ?>><label class="form-check-label" for="area_<?= $area['id'] ?>"><?= e($area['nome']) ?> (<?= e($area['lugares']) ?> lugares)</label></div><?php endforeach; ?></div></div></div><div class="col-md-4 mb-3"><label 