special!=='1');}function updateWeekdaysValidity(){const invalid=recurrence?.value==='semanal'&&!weekdayInputs.some((i)=>i.checked);weekdayInputs.forEach((i,idx)=>i.setCustomValidity(invalid&&idx===0?'Selecione ao menos um dia da semana.':''));}function maskTime(input){let digits=input.value.replace(/\D/g,'').slice(0,4);let masked=digits.length>=3?digits.slice(0,2)+':'+digits.slice(2):digits;input.value=masked;input.setSelectionRange(masked.length,masked.length);}group.addEventListener('change',loadSubs);recurrence?.addEventListener('change',()=>{const recurring=recurrence.value!=='nenhuma';opts.classList.toggle('d-none',!recurring);if(recurrenceUntil)recurrenceUntil.required=recurring;updateWeekdaysValidity();});weekdayInputs.forEach((i)=>i.addEventListener('change',updateWeekdaysValidity));[startTime,endTime].forEach((input)=>input?.addEventListener('input',()=>maskTime(input)));updateWeekdaysValidity();loadSubs();</script><?php require __DIR__.'/includes/footer.php';
